# -*- coding: utf-8 -*-
"""دفعة ابتكارات: كل الأقسام."""
from biz_tools import F, S, add, CATS, T

add('saas-metrics-calculator','finance','📈','حاسبة مؤشرات الاشتراكات (MRR/Churn/LTV)','الإيراد الشهري المتكرر ومعدل الفقد وقيمة العميل ونسبة LTV:CAC.',
 [F('c','عدد المشتركين','n',400),F('p','سعر الاشتراك الشهري','n',60),F('ch','معدل الفقد الشهري %','n',5),F('ac','تكلفة اكتساب مشترك','n',150),F('g','هامش الربح الإجمالي %','n',80)],
 r'''function compute(v){const mrr=v.c*v.p,life=v.ch>0?100/v.ch:0,ltv=v.p*v.g/100*life,ratio=v.ac?ltv/v.ac:0,pb=v.p*v.g/100?v.ac/(v.p*v.g/100):0;return kpis([kpi('MRR',f(mrr)),kpi('ARR',f(mrr*12)),kpi('عمر المشترك (شهر)',f(life,1)),kpi('LTV',f(ltv)),kpi('LTV:CAC',f(ratio,1)+'x',ratio>=3?'good':'bad'),kpi('استرداد CAC (شهر)',f(pb,1))])+rec([ratio<3?'النسبة أقل من 3: خفّض تكلفة الاكتساب أو ارفع الاحتفاظ.':'نسبة صحية: يمكنك زيادة الإنفاق التسويقي تدريجيًا.',v.ch>7?'الفقد مرتفع: ركّز على تجربة أول 30 يومًا.':'الفقد ضمن المقبول.'])}''')

add('break-even-units','finance','⚖️','حاسبة نقطة التعادل بالوحدات والإيراد','كم وحدة تبيع حتى لا تخسر؟ مع هامش الأمان.',
 [F('fx','التكاليف الثابتة الشهرية','n',20000),F('p','سعر الوحدة','n',150),F('vc','التكلفة المتغيرة للوحدة','n',90),F('q','المبيعات الحالية (وحدات)','n',500)],
 r'''function compute(v){const cm=v.p-v.vc;if(cm<=0)return'<b>هامش المساهمة سالب: لن تصل للتعادل.</b>';const u=Math.ceil(v.fx/cm),ms=v.q?(v.q-u)/v.q*100:0;return kpis([kpi('وحدات التعادل',f(u,0)),kpi('إيراد التعادل',f(u*v.p)),kpi('هامش المساهمة',f(cm)),kpi('هامش الأمان',f(ms,1)+'%',ms>=20?'good':'bad')])+rec([ms<0?'مبيعاتك الحالية أقل من التعادل.':'كلما زاد هامش الأمان زادت مناعتك ضد تراجع المبيعات.'])}''')

add('ad-budget-splitter','marketing','🎯','موزّع ميزانية الإعلانات على القنوات','وزّع ميزانيتك حسب عائد كل قناة المتوقع.',
 [F('b','الميزانية الشهرية','n',10000),F('r1','عائد القناة 1 (ROAS)','n',3.5,h='سناب/تيك توك مثلًا'),F('r2','عائد القناة 2 (ROAS)','n',2.5),F('r3','عائد القناة 3 (ROAS)','n',4.5),F('t','نسبة التجربة للقنوات الجديدة %','n',10)],
 r'''function compute(v){const x=v.b*(1-v.t/100),s=v.r1+v.r2+v.r3,a=[v.r1,v.r2,v.r3].map(r=>x*r/s);const rev=a[0]*v.r1+a[1]*v.r2+a[2]*v.r3;return tbl(['القناة','الميزانية','الإيراد المتوقع'],a.map((m,i)=>['قناة '+(i+1),f(m),f(m*[v.r1,v.r2,v.r3][i])]))+kpis([kpi('ميزانية التجربة',f(v.b*v.t/100)),kpi('إيراد متوقع',f(rev),'good')])+rec(['أعد التوزيع كل أسبوعين حسب النتائج الفعلية.','لا تضاعف ميزانية قناة دفعة واحدة؛ زد 20% كل مرة.'])}''')

add('content-calendar-30','marketing','🗓️','مولّد تقويم محتوى 30 يومًا','خطة نشر يومية بأنواع محتوى متنوعة لنشاطك.',
 [F('n','نشاطك/منتجك','text','متجر عطور'),F('a','الجمهور','text','نساء 20-40'),S('c','عدد المنشورات أسبوعيًا',[('3','3'),('5','5'),('7','7')])],
 r'''function compute(v){const T=['نصيحة تعليمية','خلف الكواليس','عرض منتج','رأي عميل','سؤال تفاعلي','مقارنة/دليل شراء','عرض محدود','قصة العلامة','أخطاء شائعة','قبل/بعد'];const d=[7,6,5,4,3,2,1].slice(0,0);const n=+v.c,rows=[];for(let i=0;i<4*n;i++){rows.push(['أسبوع '+(Math.floor(i/n)+1)+' - منشور '+(i%n+1),T[i%T.length],v.n+': '+T[i%T.length]+' موجّه إلى '+v.a])}return tbl(['الموعد','النوع','الفكرة'],rows)+rec(['صوّر دفعة واحدة تكفي أسبوعين.','ضع في كل منشور دعوة واضحة لإجراء واحد.'])+aiOut('اكتب نصوص منشورات لتقويم المحتوى التالي لنشاط '+v.n+' للجمهور '+v.a+': '+rows.map(r=>r[1]).join(' | '))}''')

add('utm-link-builder','marketing','🔗','منشئ روابط UTM للحملات','روابط تتبع جاهزة لكل قناة.',
 [F('u','رابط الصفحة','text','https://example.com/offer'),F('c','اسم الحملة','text','ramadan_sale'),F('s','القنوات (واحدة بكل سطر)','textarea','snapchat\ntiktok\ninstagram\nemail',r=4)],
 r'''function compute(v){const rows=v.s.split('\n').map(x=>x.trim()).filter(Boolean).map(s=>[s,v.u+(v.u.includes('?')?'&':'?')+'utm_source='+encodeURIComponent(s)+'&utm_medium=social&utm_campaign='+encodeURIComponent(v.c)]);return tbl(['القناة','الرابط'],rows)+rec(['استخدم أسماء حملات موحّدة بحروف صغيرة.','راقب النتائج في Google Analytics.'])}''')

add('customer-support-sla','management','🛟','مخطط مستوى خدمة الدعم (SLA)','عدد الموظفين اللازم للرد في الوقت المستهدف.',
 [F('t','عدد التذاكر يوميًا','n',120),F('m','متوسط دقائق المعالجة','n',8),F('h','ساعات العمل الفعلية للموظف','n',6),F('u','نسبة الاستغلال المستهدفة %','n',75)],
 r'''function compute(v){const w=v.t*v.m/60,n=w/(v.h*v.u/100);return kpis([kpi('ساعات عمل مطلوبة',f(w,1)),kpi('موظفون لازمون',f(Math.ceil(n),0),'good'),kpi('تذاكر/موظف',f(v.t/Math.ceil(n),0))])+rec(['أضف 15% احتياطًا للإجازات.','ردود جاهزة تخفض وقت المعالجة 30%.'])}''')

add('raci-matrix-builder','management','🧱','منشئ مصفوفة RACI','من مسؤول ومن يُستشار ومن يُبلَّغ في كل مهمة.',
 [F('t','المهام (سطر لكل مهمة)','textarea','إطلاق الحملة\nإعداد التقرير\nاعتماد الميزانية',r=4),F('p','الأشخاص (مفصولة بفاصلة)','text','سارة,أحمد,المدير')],
 r'''function compute(v){const P=v.p.split(',').map(x=>x.trim()).filter(Boolean),R=['R','A','C','I'];const rows=v.t.split('\n').filter(x=>x.trim()).map(t=>[t].concat(P.map((p,i)=>R[i%4])));return tbl(['المهمة'].concat(P),rows)+note('R=ينفّذ · A=يعتمد (واحد فقط) · C=يُستشار · I=يُبلَّغ. عدّل التوزيع حسب واقعك.')}''')

add('decision-matrix','management','🧮','مصفوفة القرار المرجّحة','قارن خيارات بمعايير وأوزان لتصل لقرار مبرر.',
 [F('c','المعايير | الوزن (سطر لكل معيار)','textarea','السعر | 40\nالجودة | 35\nالسرعة | 25',r=4),F('o','الخيارات | الدرجات 1-10 بنفس ترتيب المعايير','textarea','المورد أ | 7,8,6\nالمورد ب | 9,6,7\nالمورد ج | 6,9,8',r=4)],
 r'''function compute(v){const W=lines(v.c).map(r=>num(r[1])),tw=W.reduce((a,b)=>a+b,0)||1;const R=lines(v.o).map(r=>{const s=String(r[1]).split(',').map(Number);const sc=s.reduce((a,x,i)=>a+x*(W[i]||0),0)/tw;return[r[0],sc]}).sort((a,b)=>b[1]-a[1]);return tbl(['الخيار','الدرجة المرجّحة'],R.map(r=>[r[0],f(r[1],2)]))+rec(['الأفضل: '+(R[0]?R[0][0]:'-'),'اختبر حساسية القرار بتغيير الأوزان.'])}''')

add('recruitment-funnel','hr','🧲','محلل قمع التوظيف','أين تخسر المرشحين؟ نسب التحويل لكل مرحلة وتكلفة التوظيف.',
 [F('a','عدد المتقدمين','n',200),F('s','اجتازوا الفرز','n',50),F('i','أجريت لهم مقابلة','n',20),F('o','عروض مقدمة','n',5),F('h','تعيينات','n',3),F('c','تكلفة الإعلان والتوظيف','n',9000)],
 r'''function compute(v){const st=[['متقدمون',v.a],['فرز',v.s],['مقابلة',v.i],['عرض',v.o],['تعيين',v.h]];const rows=st.map((x,i)=>[x[0],f(x[1],0),i?f(x[1]/st[i-1][1]*100,0)+'%':'—']);return tbl(['المرحلة','العدد','التحويل'],rows)+kpis([kpi('تكلفة التعيين',f(v.h?v.c/v.h:0)),kpi('قبول العروض',f(v.o?v.h/v.o*100:0,0)+'%')])+rec(['أضعف تحويل هو المكان الأول للتحسين.','قبول العروض أقل من 70% يعني مراجعة الراتب أو سرعة الإجراءات.'])}''')

add('turnover-cost','hr','🚪','حاسبة تكلفة دوران الموظفين','كم تكلّفك استقالة موظف فعليًا؟',
 [F('s','الراتب السنوي','n',84000),F('h','تكلفة التوظيف','n',8000),F('t','تكلفة التدريب','n',6000),F('l','أشهر الإنتاجية المنخفضة','n',3),F('n','عدد الاستقالات سنويًا','n',5)],
 r'''function compute(v){const lp=v.s/12*v.l*0.5,one=v.h+v.t+lp;return kpis([kpi('تكلفة استقالة واحدة',f(one),'bad'),kpi('التكلفة السنوية',f(one*v.n),'bad'),kpi('نسبة من الراتب',f(one/v.s*100,0)+'%')])+rec(['تحسين الاحتفاظ بـ 20% يوفر '+f(one*v.n*0.2)+' سنويًا.','أجرِ مقابلات خروج وحلل الأسباب.'])}''')

add('employee-onboarding-checklist','hr','🎒','مولّد خطة تهيئة موظف جديد','قائمة أسبوع أول وشهر أول جاهزة.',
 [F('r','المسمى','text','مندوب مبيعات'),F('m','المدير','text','أحمد')],
 r'''function compute(v){const D=['قبل اليوم الأول: تجهيز الجهاز والحسابات والعقد','اليوم 1: ترحيب وجولة وتعريف بالفريق','اليوم 2-3: شرح المنتجات والأنظمة','الأسبوع 1: مرافقة زميل وأهداف أولية','الأسبوع 2: أول مهمة مستقلة مع مراجعة','اليوم 30: مراجعة أداء مع '+v.m+' وتغذية راجعة','اليوم 60: أهداف الربع','اليوم 90: تقييم نهاية التجربة'];return lines2(D)+aiOut('اكتب خطة تهيئة تفصيلية لموظف جديد بمسمى '+v.r+' مع مؤشرات نجاح لكل مرحلة.')}function lines2(a){return'<ol>'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'}''')

add('shipping-cost-estimator','ecom','🚚','مقدّر تكلفة الشحن للمنتج','تكلفة الشحن حسب الوزن الفعلي والحجمي.',
 [F('w','الوزن الفعلي (كجم)','n',1.2),F('l','الطول سم','n',30),F('b','العرض سم','n',20),F('h','الارتفاع سم','n',15),F('r','سعر الكيلو','n',9),F('d','قسمة الحجمي (5000 غالبًا)','n',5000)],
 r'''function compute(v){const vol=v.l*v.b*v.h/v.d,cw=Math.max(v.w,vol);return kpis([kpi('الوزن الحجمي',f(vol,2)+' كجم'),kpi('الوزن المحاسب',f(cw,2)+' كجم'),kpi('التكلفة',f(cw*v.r),'good')])+rec([vol>v.w?'الحجم يرفع التكلفة: جرّب تغليفًا أصغر.':'الوزن الفعلي هو المحاسب.'])}''')

add('product-title-generator','ecom','🏷️','مولّد عناوين المنتجات للبحث','عناوين تجمع الكلمات التي يبحث بها العملاء.',
 [F('p','المنتج','text','حقيبة ظهر'),F('a','الصفات (فاصلة)','text','مقاومة للماء,للابتوب,خفيفة'),F('u','الاستخدام','text','للسفر والعمل')],
 r'''function compute(v){const A=v.a.split(',').map(x=>x.trim()).filter(Boolean);const T=[v.p+' '+A.join(' ')+' '+v.u,A[0]+' '+v.p+' '+v.u,v.p+' '+v.u+' - '+(A[1]||''),'أفضل '+v.p+' '+A.slice(0,2).join(' و')];return lines2(T)+rec(['العنوان بين 60 و100 حرف.','ضع الكلمة الأهم أولًا.'])}function lines2(a){return'<ol>'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'}''')

add('daily-focus-planner','career','🎯','مخطط التركيز اليومي (3 أولويات)','رتب يومك بمصفوفة الأهمية وفترات تركيز.',
 [F('t','مهام اليوم (سطر لكل مهمة | أهمية 1-5 | دقائق)','textarea','تقرير المبيعات | 5 | 90\nالرد على الإيميلات | 2 | 30\nاجتماع الفريق | 4 | 45\nتحديث الملف | 3 | 60',r=5),F('h','دقائق التركيز المتاحة','n',240)],
 r'''function compute(v){let L=lines(v.t).map(r=>({n:r[0],i:num(r[1]),m:num(r[2])})).sort((a,b)=>b.i-a.i/1);let left=v.h;const rows=L.map(x=>{const ok=left>=x.m;if(ok)left-=x.m;return[x.n,x.i,x.m,ok?'✅ اليوم':'⏭️ غدًا']});return tbl(['المهمة','الأهمية','دقائق','القرار'],rows)+rec(['أنجز الأهم في أول ساعتين.','أغلق الإشعارات أثناء فترات التركيز.'])}''')

add('side-income-planner','career','💼','مخطط الدخل الإضافي','كم ساعة تحتاج لهدف دخل إضافي؟',
 [F('g','الهدف الشهري','n',3000),F('r','أجر الساعة المتوقع','n',60),F('h','ساعات متاحة أسبوعيًا','n',10)],
 r'''function compute(v){const hm=v.g/v.r,hw=hm/4.33;return kpis([kpi('ساعات شهريًا',f(hm,0)),kpi('ساعات أسبوعيًا',f(hw,1),hw<=v.h?'good':'bad'),kpi('المتاح',f(v.h*4.33*v.r))])+rec([hw<=v.h?'هدفك قابل للتحقيق بوقتك.':'ارفع سعر ساعتك أو أنقص الهدف أو زد الوقت.'])}''')

add('okr-progress-tracker','management','📊','متتبع تقدم OKR','نسبة إنجاز الأهداف والنتائج الرئيسية مع حالة الخطر.',
 [F('t','النتائج (وصف | الحالي | المستهدف)','textarea','زيادة المبيعات | 60 | 100\nعملاء جدد | 30 | 40\nرضا العملاء | 4.1 | 4.5',r=5),F('e','نسبة الزمن المنقضي %','n',50)],
 r'''function compute(v){const R=lines(v.t).map(r=>{const p=num(r[2])?num(r[1])/num(r[2])*100:0;return[r[0],f(p,0)+'%',p>=v.e?'🟢 على المسار':p>=v.e*0.7?'🟡 يحتاج متابعة':'🔴 متأخر']});return tbl(['النتيجة','الإنجاز','الحالة'],R)+rec(['قارن الإنجاز بنسبة الزمن المنقضي.','راجع الأهداف الحمراء أسبوعيًا.'])}''')
